-- Subject-aware Physics 7 Chapter III draft foundation, Sprint 15C.2.
-- Owner accepted the offline plan and eight drafts on 2026-10-13.
-- This creates review-only curriculum data, not an assessment contract or release.
-- Chapter II's paused migrations, existing curriculum, learner data and runtime
-- prerequisites are untouched. All content and specialist gates remain pending.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $pre$ begin
 if exists(select 1 from public.units where code='PHY7-U03')
 or exists(select 1 from public.skills where code like 'PHY7-U03-%')
 then raise exception '15C2 refuses to overwrite an existing Chapter III'; end if;
 if (select count(*) from public.subject_program_source_bindings b join public.units u on u.subject_program_id=b.subject_program_id where u.code='PHY7-U02' and b.applicability_status='governing')<>1 then raise exception '15C2 governing source binding required'; end if;
end $pre$;
do $post$ begin if (select count(*) from public.curriculum_release_skills where curriculum_release_id='b626705a-a355-5937-b20b-38550dc5b0fe'::uuid)<>8 or (select count(*) from public.curriculum_release_outcomes where curriculum_release_id='b626705a-a355-5937-b20b-38550dc5b0fe'::uuid)<>6 then raise exception '15C2 incomplete draft foundation'; end if; end $post$;
commit;
